    إذا (نص == "") { ارجع "" }
    متغير ن = ""
    متغير ح = نص[٠]
    متغير عد = ١
    من_أجل (ي من ١ إلى طول(نص) - ١) {
        إذا (نص[ي] == ح) {
            عد = عد + ١
